const rows = $input.all().map(i => i.json).filter(r => r.summary);
if (!rows.length) return [];
const icons = {urgent:'🚨',job:'💼',finance:'💶',personal:'💬',orders:'📦',newsletter:'📰',other:'✉️'};
const byCat = {};
for (const r of rows) (byCat[r.category] = byCat[r.category] || []).push(r);
let msg = '☕ Morning mail digest — ' + rows.length + ' email' + (rows.length > 1 ? 's' : '') + '\n';
for (const cat of ['urgent','job','finance','personal','orders','newsletter','other']) {
  if (!byCat[cat]) continue;
  msg += '\n' + (icons[cat]||'') + ' ' + cat.toUpperCase() + '\n';
  for (const r of byCat[cat]) msg += '• ' + r.summary + '\n';
}
return [{ json: { message: msg.slice(0, 4000) } }];
